<script>
(function () {
  var gatilho = null;
  var FOCAVEIS = 'a[href],button:not([disabled]),input:not([disabled])';

  function abrirModal(id, origem) {
    var m = document.getElementById(id);
    if (!m) return;
    gatilho = origem || document.activeElement;
    m.hidden = false;
    document.body.style.overflow = 'hidden';
    (m.querySelector('input') || m.querySelector('.modal-acoes button') || m.querySelector('button')).focus();
  }
  function fecharModal(m) {
    m.hidden = true;
    document.body.style.overflow = '';
    if (gatilho) gatilho.focus();
  }
  window.abrirModal = abrirModal;

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('button[type="button"]')) fecharModal(m);
    });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { e.stopPropagation(); fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var itens = m.querySelectorAll(FOCAVEIS);
      var primeiro = itens[0], ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  var btnAjuda = document.querySelector('[aria-controls="gaveta"]');
  var gaveta = document.getElementById('gaveta');
  function alternarGaveta(abrir) {
    gaveta.hidden = !abrir;
    btnAjuda.setAttribute('aria-expanded', String(abrir));
  }
  btnAjuda.addEventListener('click', function () { alternarGaveta(gaveta.hidden); });
  gaveta.querySelector('[data-fechar-gaveta]').addEventListener('click', function () {
    alternarGaveta(false);
    btnAjuda.focus();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !gaveta.hidden) { alternarGaveta(false); btnAjuda.focus(); }
  });

  var dispensar = document.querySelector('.banner .btn-txt');
  dispensar.addEventListener('click', function () {
    dispensar.closest('.banner').remove();
    document.getElementById('conteudo').focus();
  });
})();
</script>
</body>
